SELECT "countryCode" AS market,count(*)::int jobs,count(*) FILTER(WHERE raw IS NOT NULL)::int raw,count(*) FILTER(WHERE nullif(city,'') IS NOT NULL)::int city,count(*) FILTER(WHERE nullif("adminArea1",'') IS NOT NULL)::int region,count(*) FILTER(WHERE nullif("postalCode",'') IS NOT NULL)::int postal,count(*) FILTER(WHERE latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)::int coordinates,count(*) FILTER(WHERE "postedAt" IS NOT NULL)::int posted,count(*) FILTER(WHERE "validThrough" IS NOT NULL)::int expires,count(*) FILTER(WHERE length(description)>=200)::int description,count(*) FILTER(WHERE "jobFunction" IS NOT NULL)::int family,count(*) FILTER(WHERE "occupationCode" IS NOT NULL)::int occupation,count(*) FILTER(WHERE "employmentTerm" IS NOT NULL)::int term,count(*) FILTER(WHERE "workTime" IS NOT NULL)::int worktime,count(*) FILTER(WHERE "programType" IS NOT NULL)::int program,count(*) FILTER(WHERE "isSeasonal" IS NOT NULL)::int seasonal,count(*) FILTER(WHERE "engagementType" IS NOT NULL)::int engagement,count(*) FILTER(WHERE "workSchedule" IS NOT NULL)::int schedule,count(*) FILTER(WHERE "workplaceType" IS NOT NULL)::int workplace,count(*) FILTER(WHERE "experienceYears" IS NOT NULL)::int experience,count(*) FILTER(WHERE "educationLevel" IS NOT NULL)::int education,count(*) FILTER(WHERE "salaryMin">0 OR "salaryMax">0)::int salary,count(*) FILTER(WHERE "language" IS NOT NULL)::int language,count(*) FILTER(WHERE cardinality(skills)>0)::int skills,count(*) FILTER(WHERE "countryIntegrity" IS NOT NULL)::int country_integrity_present FROM "Job" WHERE "isActive" AND "mergedIntoId" IS NULL AND "withdrawnAt" IS NULL GROUP BY 1 ORDER BY jobs DESC;
